'use strict';
const nearbyHelpers=[{id:'minhanh',name:'Minh Anh',initials:'MA',age:22,range:'0,8 km',color:'orange',skills:['Zalo','Gọi video','Cỡ chữ'],bio:'Cháu hướng dẫn chậm, chia từng bước và để bác tự thao tác. Hồ sơ dùng để trình diễn.'},{id:'tuananh',name:'Tuấn Anh',initials:'TA',age:24,range:'1,2 km',color:'blue',skills:['Gửi ảnh','Android','Wi-Fi'],bio:'Cháu có thể hướng dẫn các thao tác điện thoại thông dụng. Hồ sơ dùng để trình diễn.'}];
let livePosition=null,locating=false;
const sessionPrice=99000;
function mapsURL(place,directions=false){const u=new URL(directions?'https://www.google.com/maps/dir/':'https://www.google.com/maps/search/');u.searchParams.set('api','1');u.searchParams.set(directions?'destination':'query',place);if(directions)u.searchParams.set('travelmode','walking');return u.href}
function miniMap(){return `<div class="local-map" role="img" aria-label="Sơ đồ minh họa hai người hỗ trợ quanh một điểm sinh hoạt, không phải vị trí thực"><div class="map-park park-one"></div><div class="map-park park-two"></div><div class="map-road road-one"></div><div class="map-road road-two"></div><div class="map-road road-three"></div><span class="map-place-label">Điểm sinh hoạt</span><span class="map-me">Bác</span><span class="map-helper helper-one">MA</span><span class="map-helper helper-two">TA</span><span class="map-disclaimer">SƠ ĐỒ MINH HỌA · KHÔNG PHẢI GPS THẬT</span></div>`}
function nearby(){if(state.role!=='senior')return supportRequests();return `<button class="back-btn" data-screen="home">${icon('back')} Về trang chủ</button><h1 class="screen-title">Có người chỉ tận tay</h1><p class="screen-subtitle">Chọn việc cần giúp, tìm người hướng dẫn quanh bác.</p><div class="service-price">${icon('calendar')}<span><strong>99.000đ / 45 phút</strong><small>Giá thử nghiệm · Chỉ đặt lịch mẫu</small></span></div><h2 class="section-label">Bác đang cần giúp việc gì?</h2><div class="service-issues">${['Gọi video','Gửi ảnh','Chữ khó đọc','Việc khác'].map(issue=>`<button class="chip ${state.supportIssue===issue?'active':''}" data-support-issue="${issue}">${issue}</button>`).join('')}</div><h2 class="section-label">Chọn khu vực của bác</h2><button class="secondary wide" data-action="locate-support" ${locating?'disabled':''}>${icon('locate')} ${locating?'Đang xin vị trí…':'Dùng vị trí của tôi'}</button><p class="subtle-note">${livePosition?'Đã lấy vị trí trên thiết bị; chưa chia sẻ cho người hỗ trợ.':'Bác có thể bỏ qua định vị và chọn một điểm công cộng bên dưới.'}</p><label class="field-label" for="support-area">Điểm hẹn công cộng hoặc khu vực</label><input class="form-control" id="support-area" maxlength="160" value="${esc(state.supportLandmark||'Hồ Hoàn Kiếm, Hà Nội')}" placeholder="Ví dụ: nhà văn hóa, thư viện, quán cà phê"><a class="maps-link" href="${esc(mapsURL(state.supportLandmark||'Hồ Hoàn Kiếm, Hà Nội'))}" id="support-map-link" target="_blank" rel="noopener">${icon('pin')} Xem khu vực trên Google Maps ${icon('arrow')}</a>${livePosition?`<a class="maps-link" href="${esc(mapsURL(livePosition.latitude+','+livePosition.longitude))}" target="_blank" rel="noopener">Xem vị trí vừa cấp quyền trên Google Maps ↗</a>`:''}${miniMap()}<p class="subtle-note">Hồ sơ và khoảng cách bên dưới đều là mẫu, không thay đổi theo GPS. Chưa có kết nối với người hỗ trợ thật.</p><h2 class="section-label">Người hướng dẫn mẫu</h2>${nearbyHelpers.map(h=>`<article class="friend-card">${person(h.name,h.initials,`${h.age} tuổi · Khoảng cách mẫu ${h.range}`,h.color)}<div class="interest-tags">${h.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div><button class="secondary wide" data-support-helper="${h.id}">Xem người hướng dẫn ${icon('chevron')}</button></article>`).join('')}${state.support?'<button class="primary wide" data-screen="appointment">Xem lịch hướng dẫn của bác</button>':''}<p class="subtle-note">Hướng dẫn thao tác điện thoại, chưa nhận sửa phần cứng hay thực hiện giao dịch ngân hàng.</p>`}
function helperProfile(){if(state.role!=='senior')return denied();const h=nearbyHelpers.find(h=>h.id===state.helperId)||nearbyHelpers[0];return `<button class="back-btn" data-screen="nearby">${icon('back')} Về người hỗ trợ gần bác</button><div class="profile-hero">${avatar(h.initials,h.color)}<div><h1 class="screen-title">${h.name}</h1><p>${h.age} tuổi · Người hướng dẫn mẫu</p></div></div><span class="tag">${icon('shield')} Xác thực & tập huấn · Mô phỏng</span><p class="question-body">${h.bio}</p><form id="support-booking-form"><div class="service-price"><span><strong>99.000đ / 45 phút</strong><small>Giá minh họa · Không thanh toán trong demo</small></span></div><label class="field-label" for="booking-issue">Bác muốn được chỉ việc gì?</label><select class="form-control" id="booking-issue" name="issue">${['Gọi video','Gửi ảnh','Chữ khó đọc','Việc khác'].map(i=>`<option ${i===state.supportIssue?'selected':''}>${i}</option>`).join('')}</select><label class="field-label" for="booking-place">Điểm hẹn công cộng bác chọn</label><input class="form-control" id="booking-place" name="place" required minlength="5" maxlength="160" value="${esc(state.supportLandmark||'Hồ Hoàn Kiếm, Hà Nội')}"><label class="field-label" for="booking-slot">Khung giờ mong muốn</label><select class="form-control" id="booking-slot" name="slot"><option>Ngày mai · 09:00–09:45 (mẫu)</option><option>Ngày mai · 14:00–14:45 (mẫu)</option><option>Ngày mai · 16:00–16:45 (mẫu)</option></select><label class="consent-label"><input type="checkbox" name="consent" required> <span>Tôi đồng ý chia sẻ việc cần giúp và điểm hẹn này với ${h.name} khi gửi yêu cầu mẫu.</span></label><div class="safe-note">${icon('shield')} Bác tự giữ điện thoại và tự thao tác. Không chia sẻ mật khẩu, mã OTP hay giao điện thoại cho người hỗ trợ mang đi.</div><button class="primary wide" type="submit">Gửi yêu cầu mẫu ${icon('arrow')}</button><p class="subtle-note">Sau khi hai bên xác nhận, mới chốt lịch và điểm hẹn cụ thể. Demo chỉ lưu trên máy này, chưa gửi thông tin cho ai.</p></form>`}
function appointment(){if(state.role!=='senior')return supportRequests();const b=state.support;if(!b)return `<h1 class="screen-title">Bác chưa có lịch hướng dẫn</h1><p class="screen-subtitle">Mình chọn người hướng dẫn và điểm hẹn trước nhé.</p><button class="primary wide" data-screen="nearby">Tìm người hướng dẫn</button>`;const h=nearbyHelpers.find(h=>h.id===b.helperId)||nearbyHelpers[0];const labels={pending:'Chờ người hỗ trợ nhận · Mẫu',accepted:'Hai bên đã xác nhận · Mẫu',finished:'Đã kết thúc buổi hướng dẫn · Mẫu',cancelled:'Đã hủy yêu cầu mẫu'};return `<button class="back-btn" data-screen="nearby">${icon('back')} Về hỗ trợ gần bác</button><h1 class="screen-title">Lịch hướng dẫn của bác</h1><span class="tag ${b.status==='pending'?'orange':''}">${labels[b.status]||labels.pending}</span>${person(h.name,h.initials,'Người hướng dẫn · Hồ sơ mẫu',h.color)}<div class="community-post summary-card"><div class="stat-row"><span>Việc cần giúp</span><strong>${esc(b.issue)}</strong></div><div class="stat-row"><span>Khung giờ</span><strong class="wrap-value">${esc(b.slot)}</strong></div><div class="stat-row"><span>Điểm hẹn</span><strong class="wrap-value">${esc(b.place)}</strong></div><div class="stat-row"><span>Giá đã xem</span><strong>${vnd(b.price)}</strong></div></div><a class="maps-link" href="${esc(mapsURL(b.place,true))}" target="_blank" rel="noopener">${icon('pin')} Chỉ đường bằng Google Maps ${icon('arrow')}</a>${b.status==='pending'?'<p class="notice">Để trình diễn: đổi sang vai người trẻ → mở “Yêu cầu hướng dẫn” → nhận yêu cầu mẫu. Không có lịch hẹn thật được tạo.</p>':''}${b.status==='accepted'?`<div class="safe-note">${icon('shield')} Khi gặp, bác đối chiếu tên và hồ sơ trong An Vui. Bác có thể đi cùng người thân. Chỉ xác nhận xong khi tự làm được thao tác cần học.</div><button class="primary wide" data-action="finish-support">${icon('check')} Tôi đã được hướng dẫn xong</button>`:''}${['pending','accepted'].includes(b.status)?'<button class="secondary wide" data-action="cancel-support">Hủy yêu cầu mẫu</button>':''}${b.status==='finished'?'<div class="notice">Buổi hướng dẫn mẫu đã hoàn tất. Không phát sinh thanh toán. Trong dịch vụ đề xuất, phí nền tảng chỉ ghi nhận với buổi đủ điều kiện hoàn tất.</div>':''}`}
function supportRequests(){if(state.role!=='helper')return nearby();const b=state.support;return `<button class="back-btn" data-screen="home">${icon('back')} Về trang chủ</button><h1 class="screen-title">Yêu cầu hướng dẫn</h1><p class="screen-subtitle">Hướng dẫn từng bước, để cô bác tự làm được.</p>${!b||b.status==='cancelled'?'<div class="empty">Chưa có yêu cầu mẫu đang chờ.<br>Đổi sang vai cô bác và đặt một buổi hướng dẫn để thử.</div>':`<article class="community-post">${person('Bác Minh','M','Yêu cầu mẫu · Chưa kết nối người thật')}<h2 class="card-title">${esc(b.issue)}</h2><p>${esc(b.place)}<br>${esc(b.slot)}</p><div class="stat-row"><span>Tổng giá mẫu</span><strong>${vnd(b.price)}</strong></div><div class="stat-row"><span>Phí nền tảng 20%</span><strong>${vnd(b.price*.2)}</strong></div><div class="stat-row"><span>Phần người hỗ trợ trước chi phí</span><strong>${vnd(b.price*.8)}</strong></div><p class="subtle-note">Yêu cầu gửi đến ${esc(nearbyHelpers.find(h=>h.id===b.helperId)?.name||'người hỗ trợ')}. Vai người trẻ đang mô phỏng đúng hồ sơ được chọn. Chỉ nhận khi đủ năng lực, khung giờ và khu vực.</p>${b.status==='pending'?'<button class="primary wide" data-action="accept-support">Nhận yêu cầu mẫu</button>':`<div class="notice">${b.status==='accepted'?'Đã nhận mẫu. Đổi về vai cô bác → “Xem lịch của bác” để xác nhận hoàn tất.':'Cô bác đã xác nhận hoàn tất mẫu.'}</div>`}</article>`}<div class="safe-note">${icon('shield')} Không hỏi mật khẩu, mã OTP, mở ứng dụng ngân hàng hay nhận giữ điện thoại. Nhận buổi có phí cần hồ sơ dịch vụ được duyệt riêng.</div>`}
function serviceRevenue(){return `<section class="service-business"><div><div class="eyebrow">NGUỒN THU MỚI · HƯỚNG DẪN TRỰC TIẾP</div><h2>Chỉ tận tay, trả phí theo buổi.</h2><p>Hỏi đáp online tiếp tục miễn phí. Khi cần gặp trực tiếp, cô bác hoặc con cháu đặt buổi hướng dẫn với giá và điểm hẹn được chốt trước.</p><button class="primary" data-action="campaign-demo">Thử đặt người hướng dẫn ${icon('arrow')}</button></div><div class="service-unit"><div class="stat-row"><span>Một buổi 45 phút</span><strong>99.000đ</strong></div><div class="stat-row"><span>Người hỗ trợ nhận 80%</span><strong>79.200đ</strong></div><div class="stat-row"><span>Doanh thu nền tảng 20%</span><strong>19.800đ</strong></div><p>Giả định chi phí biến đổi 7.000đ/buổi → còn 12.800đ đóng góp trước chi phí cố định và thuế. Đây là giả định để thử nghiệm. Nguồn thu này chưa cộng vào bảng tính ba nguồn bên dưới.</p></div></section>`}
function campaign(){return `<section class="campaign-page"><div class="campaign-intro"><div><div class="eyebrow">CHIẾN DỊCH AN VUI · Ý TƯỞNG THỬ NGHIỆM</div><h1>Để ba mẹ<br>không <em>ngại hỏi.</em></h1><p>Con chỉ qua điện thoại, ba mẹ vẫn chưa tìm thấy nút.<br>Thêm một lời chỉ tận tay, bớt một lần cả nhà khó xử.</p><div class="campaign-actions"><button class="primary" data-action="campaign-demo">Thử tìm người hỗ trợ gần bác ${icon('arrow')}</button><a class="secondary" href="assets/campaign-story.jpg" download="An-Vui-De-ba-me-khong-ngai-hoi.jpg">${icon('download')} Tải ảnh kể chuyện</a></div><div class="campaign-tone">Chỉ tận tay. Hiểu từng bước.<br><span>Giúp ba mẹ tự tin, để những cuộc gọi lại là niềm vui.</span></div></div><figure class="campaign-poster"><img src="assets/campaign-story.webp" alt="Quảng cáo kể chuyện: mẹ gọi con nhờ chỉ điện thoại, con đang bận và mất kiên nhẫn; mẹ tự hỏi trên An Vui, tìm người hỗ trợ gần mình; bạn trẻ kiên nhẫn hướng dẫn tại điểm hẹn để mẹ tự gọi video cho con."><figcaption>Ảnh quảng cáo bằng AI · Nhân vật hư cấu · Dịch vụ đề xuất</figcaption></figure></div><div class="campaign-storyline"><article><span>01 · CHUYỆN NHIỀU NHÀ</span><h2>“Con ơi, mẹ bấm chỗ nào?”</h2><p>Con nói “góc phải”, mẹ nhìn thấy nhiều nút. Con sốt ruột. Mẹ lặng đi: “Thôi, để mẹ tự mò.”</p></article><article><span>02 · MỘT CÁCH HỎI KHÁC</span><h2>“Bác hỏi ở đây nhé.”</h2><p>Đặt câu hỏi trên An Vui. Nếu online chưa đủ, chọn người hỗ trợ quanh mình và hẹn nơi thuận tiện.</p></article><article><span>03 · BA MẸ TỰ LÀM ĐƯỢC</span><h2>“Lần này, mẹ tự gọi rồi!”</h2><p>Người trẻ chỉ từng bước; ba mẹ tự bấm trên máy của mình. Cuộc gọi sau có thêm một nụ cười.</p></article></div><section class="campaign-keyvisual"><img src="assets/campaign-keyvisual.webp" alt="Người mẹ tự tin tự dùng điện thoại bên cạnh một bạn trẻ hướng dẫn tận tình tại điểm sinh hoạt cộng đồng" loading="lazy"><div><div class="eyebrow">LỜI HỨA DỊCH VỤ</div><h2>Có người ở gần.<br>Có lời chỉ tận tay.</h2><p>Hỗ trợ gọi video, gửi ảnh, chỉnh cỡ chữ và những việc điện thoại hằng ngày. Để ba mẹ hiểu và tự thực hiện.</p><button class="primary" data-action="campaign-demo">Cùng ba mẹ dùng thử An Vui ${icon('arrow')}</button><small>Đặt lịch trong bản demo là mô phỏng. Chưa mở dịch vụ thật.</small></div></section><div class="strategy-columns"><article class="strategy-section"><h2>Quảng cáo dẫn đến hành động nào?</h2><ol><li><strong>Người con nhận ra tình huống quen.</strong> Video ngắn 30 giây và ảnh kể chuyện, không gán nhãn con bất hiếu hay ba mẹ kém cỏi.</li><li><strong>Mở đúng việc ba mẹ cần.</strong> Landing page dẫn thẳng đến đặt câu hỏi hoặc “Có người chỉ tận tay”.</li><li><strong>Cùng ba mẹ hoàn thành bước đầu.</strong> Chọn việc cần giúp, khu vực, người hướng dẫn và điểm hẹn.</li><li><strong>Đo buổi hoàn tất.</strong> Tách người quan tâm, yêu cầu hợp lệ và buổi có xác nhận; không lấy lượt thích làm bằng chứng kinh doanh.</li></ol></article><article class="strategy-section"><h2>Chạy thử ở một khu vực nhỏ</h2><p><strong>Tệp chính:</strong> con cháu trưởng thành có ba mẹ dùng điện thoại, sống hoặc làm việc xa nhau. Thông điệp phụ cho cô bác: “Cứ hỏi nhé, có người chỉ từng bước.”</p><p><strong>Kênh:</strong> video ngắn trên Facebook, TikTok; ảnh trong nhóm cộng đồng được quản trị viên cho phép; buổi hướng dẫn tại câu lạc bộ người cao tuổi.</p><p><strong>Giả định ngân sách truyền thông:</strong> 3 triệu / 14 ngày: 1,8 triệu thử tiếp cận mới, 600.000đ phân phối nội dung người đã quan tâm, 600.000đ vật liệu và hoạt động địa bàn. Chưa gồm nhân sự, quà tặng hay trợ giá.</p></article></div>${serviceRevenue()}<section class="strategy-section"><h2>Kịch bản phim 30 giây</h2><table class="metric-table"><thead><tr><th>Thời gian</th><th>Hình & lời thoại</th><th>Mục đích</th></tr></thead><tbody><tr><td>0–8 giây</td><td>Mẹ: “Con ơi, mẹ bấm chỗ nào?” Con vừa làm vừa đáp: “Mẹ bấm như con vừa nói đi!”</td><td>Nhận ra tình huống, thấy cả hai đang khó</td></tr><tr><td>8–12 giây</td><td>Mẹ nhìn máy: “Thôi, để mẹ tự mò vậy.” Con khựng lại.</td><td>Khoảng lặng, không đổ lỗi</td></tr><tr><td>12–20 giây</td><td>Mẹ đặt câu hỏi An Vui, chọn người hỗ trợ và điểm hẹn. Người trẻ: “Bác cứ bấm thử, cháu chỉ từng bước.”</td><td>Giải thích dịch vụ qua thao tác</td></tr><tr><td>20–26 giây</td><td>Mẹ tự gọi video: “Lần này mẹ tự gọi được rồi!” Con mỉm cười: “Mẹ giỏi quá!”</td><td>Trả lại sự chủ động cho ba mẹ</td></tr><tr><td>26–30 giây</td><td>An Vui. Chỉ tận tay. Hiểu từng bước. Cùng ba mẹ dùng thử.</td><td>Một lời kêu gọi rõ ràng</td></tr></tbody></table></section><div class="campaign-copy"><h2>Nội dung bài đăng mẫu</h2><p>“Mẹ bấm như con vừa nói đi!”<br>Có khi mình đã nói câu ấy trong một ngày quá bận.<br>Nhưng phía bên kia, mẹ chỉ đang chưa tìm thấy nút cần bấm.</p><p>Với An Vui, ba mẹ có thể đặt câu hỏi, chọn người hướng dẫn ở gần và được chỉ từng bước trên chính điện thoại của mình.</p><p><strong>Để ba mẹ không ngại hỏi.<br>Chỉ tận tay. Hiểu từng bước.</strong></p><p>Cùng ba mẹ dùng thử An Vui. Dịch vụ trực tiếp đang ở giai đoạn ý tưởng, chưa nhận lịch hẹn thật.</p><button class="secondary" data-action="copy-campaign">${icon('copy')} Sao chép nội dung</button></div><div class="sources">Bản đồ trong app là sơ đồ minh họa. Nút Google Maps mở dịch vụ Google theo khu vực/điểm hẹn do người dùng chọn, theo <a href="https://developers.google.com/maps/documentation/urls/get-started" target="_blank" rel="noopener">tài liệu Maps URLs</a>. Không có danh sách người hỗ trợ trực tiếp theo thời gian thực. Bộ ảnh và số liệu quảng cáo là đề xuất, chưa phải chiến dịch đã chạy.</div></section>`}
const featureActions={
 'campaign-demo'(){state.role='senior';screenTo('nearby');window.scrollTo({top:0,behavior:'smooth'})},
 'locate-support'(){if(!navigator.geolocation){toast('Thiết bị chưa hỗ trợ định vị. Bác nhập khu vực hoặc điểm hẹn nhé.');return}locating=true;renderScreen();navigator.geolocation.getCurrentPosition(pos=>{livePosition={latitude:pos.coords.latitude,longitude:pos.coords.longitude};locating=false;if(state.screen==='nearby')renderScreen();toast('Đã lấy vị trí trên thiết bị. Danh sách hỗ trợ vẫn là dữ liệu mẫu.');},()=>{locating=false;if(state.screen==='nearby')renderScreen();toast('Chưa lấy được vị trí. Bác vẫn có thể nhập địa điểm công cộng để thử.');},{enableHighAccuracy:false,timeout:10000,maximumAge:60000})},
 'accept-support'(){if(state.role!=='helper'||!state.support||state.support.status!=='pending')return;state.support.status='accepted';persist();renderScreen();toast('Đã nhận yêu cầu mẫu. Chưa có thông tin nào được gửi ra ngoài.')},
 'finish-support'(){if(state.role!=='senior'||state.support?.status!=='accepted')return;state.support.status='finished';persist();renderScreen();toast('Đã xác nhận hoàn tất mẫu. Không phát sinh thanh toán.')},
 'cancel-support'(){if(state.role!=='senior'||!['pending','accepted'].includes(state.support?.status))return;state.support.status='cancelled';persist();renderScreen();toast('Đã hủy yêu cầu trong demo')},
 async 'copy-campaign'(){const t='“Mẹ bấm như con vừa nói đi!”\nCó khi mình đã nói câu ấy trong một ngày quá bận.\nNhưng phía bên kia, mẹ chỉ đang chưa tìm thấy nút cần bấm.\n\nVới An Vui, ba mẹ có thể đặt câu hỏi, chọn người hướng dẫn ở gần và được chỉ từng bước trên chính điện thoại của mình.\n\nĐể ba mẹ không ngại hỏi.\nChỉ tận tay. Hiểu từng bước.\n\nCùng ba mẹ dùng thử An Vui. Dịch vụ trực tiếp đang ở giai đoạn ý tưởng, chưa nhận lịch hẹn thật.';try{await navigator.clipboard.writeText(t);toast('Đã sao chép nội dung mẫu')}catch{toast('Bác chọn nội dung trên trang để sao chép nhé.')}}
};
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.supportHelper){if(state.role!=='senior')return;state.helperId=el.dataset.supportHelper;screenTo('helper-detail')}if(el.dataset.supportIssue){state.supportIssue=el.dataset.supportIssue;persist();renderScreen()}});
document.addEventListener('input',e=>{if(e.target.id==='support-area'){state.supportLandmark=e.target.value;persist();const link=document.querySelector('#support-map-link');if(link)link.href=mapsURL(e.target.value||'Hồ Hoàn Kiếm, Hà Nội')}});
document.addEventListener('submit',e=>{if(e.target.id!=='support-booking-form')return;e.preventDefault();if(state.role!=='senior')return;const data=new FormData(e.target);if(!data.get('consent')){toast('Bác xác nhận đồng ý chia sẻ điểm hẹn với người đã chọn trước nhé.');return}const place=String(data.get('place')||'').trim();if(place.length<5){toast('Bác ghi rõ hơn điểm hẹn công cộng nhé.');return}if(state.support&&['pending','accepted'].includes(state.support.status)){toast('Bác đã có một yêu cầu đang chờ. Hãy hoàn tất hoặc hủy trước khi tạo yêu cầu mới.');return}state.support={helperId:state.helperId||'minhanh',issue:String(data.get('issue')),place,slot:String(data.get('slot')),price:sessionPrice,status:'pending'};state.supportLandmark=place;persist();screenTo('appointment');toast('Đã tạo yêu cầu mẫu trên máy này. Chưa gửi cho người thật.')});
